1	/* Host-side harness for the KWS engine: builds the exact same C sources
2	 * that go into the firmware and checks them against the Python pipeline.
3	 *
4	 *   ./kws_host golden                 parity vs torch/numpy (kws_golden.h)
5	 *   ./kws_host wav <f.wav> [thr]      stream one file, print detections
6	 *   ./kws_host batch <dir> <0|1> [thr]  all wavs in dir, expect label,
7	 *                                     print detect rate / false alarms
8	 *
9	 * WAVs must be 16 kHz mono s16 (what the pipeline produces).
10	 *
11	 * SPDX-License-Identifier: Apache-2.0
12	 */
13	
14	#include <dirent.h>
15	#include <math.h>
16	#include <stdio.h>
17	#include <stdlib.h>
18	#include <string.h>
19	
20	#include "kws.h"
21	#include "kws_tables.h"
22	#include "kws_golden.h"
23	
24	#define CHUNK 224          /* one rpmsg PCM chunk, like on the wire */
25	
26	static int g_detections;
27	static float g_first_prob;
28	static double g_first_t;
29	static double g_now_t;
30	
31	static void on_detect(float prob, void *arg)
32	{
33	  (void)arg;
34	  if (g_detections == 0)
35	    {
36	      g_first_prob = prob;
37	      g_first_t = g_now_t;
38	    }
39	
40	  g_detections++;
41	  printf("  DETECT t=%.2fs smoothed=%.3f\n", g_now_t, prob);
42	}
43	
44	static int16_t *read_wav(const char *path, long *n_out)
45	{
46	  FILE *f = fopen(path, "rb");
47	  unsigned char h[12];
48	  int16_t *pcm = NULL;
49	  long n = 0;
50	
51	  if (f == NULL)
52	    {
53	      fprintf(stderr, "cannot open %s\n", path);
54	      return NULL;
55	    }
56	
57	  if (fread(h, 1, 12, f) != 12 || memcmp(h, "RIFF", 4) ||
58	      memcmp(h + 8, "WAVE", 4))
59	    {
60	      fprintf(stderr, "%s: not a RIFF/WAVE\n", path);
61	      fclose(f);
62	      return NULL;
63	    }
64	
65	  for (; ; )
66	    {
67	      unsigned char ch[8];
68	      unsigned long sz;
69	
70	      if (fread(ch, 1, 8, f) != 8)
71	        {
72	          break;
73	        }
74	
75	      sz = (unsigned long)ch[4] | ((unsigned long)ch[5] << 8) |
76	           ((unsigned long)ch[6] << 16) | ((unsigned long)ch[7] << 24);
77	
78	      if (!memcmp(ch, "fmt ", 4))
79	        {
80	          unsigned char fmt[16];
81	
82	          if (sz < 16 || fread(fmt, 1, 16, f) != 16)
83	            {
84	              break;
85	            }
86	
87	          if ((fmt[0] | (fmt[1] << 8)) != 1 || fmt[2] != 1 ||
88	              (fmt[4] | (fmt[5] << 8) | (fmt[6] << 16)) != KWS_SR ||
89	              (fmt[14] | (fmt[15] << 8)) != 16)
90	            {
91	              fprintf(stderr, "%s: need 16 kHz mono s16 PCM\n", path);
92	              fclose(f);
93	              return NULL;
94	            }
95	
96	          if (sz > 16)
97	            {
98	              fseek(f, (long)sz - 16, SEEK_CUR);
99	            }
100	        }
101	      else if (!memcmp(ch, "data", 4))
102	        {
103	          n = (long)sz / 2;
104	          pcm = malloc(n * sizeof(int16_t));
105	          if (pcm == NULL || fread(pcm, 2, n, f) != (size_t)n)
106	            {
107	              free(pcm);
108	              pcm = NULL;
109	            }
110	
111	          break;
112	        }
113	      else
114	        {
115	          fseek(f, (long)((sz + 1) & ~1ul), SEEK_CUR);
116	        }
117	    }
118	
119	  fclose(f);
120	  if (pcm == NULL)
121	    {
122	      fprintf(stderr, "%s: no data chunk\n", path);
123	    }
124	
125	  *n_out = n;
126	  return pcm;
127	}
128	
129	static void stream(const int16_t *pcm, long n)
130	{
131	  static const int16_t silence[CHUNK];
132	  long i;
133	
134	  for (i = 0; i < n; i += CHUNK)
135	    {
136	      long c = n - i < CHUNK ? n - i : CHUNK;
137	
138	      g_now_t = (double)i / KWS_SR;
139	      kws_engine_push(&pcm[i], (size_t)c);
140	    }
141	
142	  /* A real microphone keeps running after the phrase; without this tail
143	   * the score smoother never gets its post-phrase inferences and late
144	   * detections are lost at end-of-file.
145	   */
146	
147	  for (i = 0; i < (long)(KWS_SR * 6 / 10); i += CHUNK)
148	    {
149	      g_now_t = (double)(n + i) / KWS_SR;
150	      kws_engine_push(silence, CHUNK);
151	    }
152	}
153	
154	static int run_golden(void)
155	{
156	  int fail = 0;
157	  int gi;
158	
159	  for (gi = 0; gi < KWS_GOLDEN_COUNT; gi++)
160	    {
161	      const struct kws_golden_case *g = &g_kws_golden[gi];
162	      float feat[KWS_NMEL];
163	      float maxd = 0.0f;
164	      float prob;
165	      float pd;
166	      int i;
167	      int m;
168	
169	      for (i = 0; i < g->nframes; i++)
170	        {
171	          kws_frontend_frame(&g->pcm[i * KWS_HOP], feat);
172	
173	          for (m = 0; m < KWS_NMEL; m++)
174	            {
175	              float d = fabsf(feat[m] - g->feat[i * KWS_NMEL + m]);
176	
177	              if (d > maxd)
178	                {
179	                  maxd = d;
180	                }
181	            }
182	        }
183	
184	      prob = kws_nn_infer(g->feat);      /* python features -> C net */
185	      pd = fabsf(prob - *g->prob);
186	
187	      printf("%-6s frames=%d  max|feat C-py|=%.2e  "
188	             "prob C=%.6f py=%.6f |d|=%.2e  %s\n",
189	             g->name, g->nframes, maxd, prob, *g->prob, pd,
190	             (maxd < 5e-3f && pd < 2e-3f) ? "PASS" : "FAIL");
191	
192	      if (!(maxd < 5e-3f && pd < 2e-3f))
193	        {
194	          fail = 1;
195	        }
196	    }
197	
198	  return fail;
199	}
200	
201	static void report(const char *path)
202	{
203	  kws_stats_t st;
204	
205	  kws_engine_get_stats(&st);
206	  printf("%s: detections=%d peak=%.3f last_infer=%uus\n",
207	         path, g_detections, st.peak, st.infer_us);
208	}
209	
210	int main(int argc, char **argv)
211	{
212	  if (argc >= 2 && strcmp(argv[1], "golden") == 0)
213	    {
214	      return run_golden();
215	    }
216	
217	  if (argc >= 2 && strcmp(argv[1], "test") == 0)
218	    {
219	      float pz;
220	      float po;
221	
222	      kws_engine_selftest(&pz, &po);
223	      printf("selftest z=%lu o=%lu (micro)\n",
224	             (unsigned long)(pz * 1e6f + 0.5f),
225	             (unsigned long)(po * 1e6f + 0.5f));
226	      return 0;
227	    }
228	
229	  if (argc >= 3 && strcmp(argv[1], "wav") == 0)
230	    {
231	      long n;
232	      int16_t *pcm = read_wav(argv[2], &n);
233	
234	      if (pcm == NULL)
235	        {
236	          return 1;
237	        }
238	
239	      kws_engine_init(on_detect, NULL);
240	      if (argc >= 4)
241	        {
242	          kws_engine_set_threshold((float)atof(argv[3]));
243	        }
244	
245	      g_detections = 0;
246	      stream(pcm, n);
247	      report(argv[2]);
248	      free(pcm);
249	      return 0;
250	    }
251	
252	  if (argc >= 4 && strcmp(argv[1], "batch") == 0)
253	    {
254	      int expect = atoi(argv[3]);
255	      DIR *d = opendir(argv[2]);
256	      struct dirent *e;
257	      int total = 0;
258	      int hit = 0;
259	      int events = 0;
260	      double sum_first = 0.0;
261	
262	      if (d == NULL)
263	        {
264	          fprintf(stderr, "cannot open dir %s\n", argv[2]);
265	          return 1;
266	        }
267	
268	      while ((e = readdir(d)) != NULL)
269	        {
270	          char path[1024];
271	          long n;
272	          int16_t *pcm;
273	
274	          if (strstr(e->d_name, ".wav") == NULL)
275	            {
276	              continue;
277	            }
