4	 * Streaming glue around the front end and the network:
5	 *
6	 *   push(pcm) -> 400-sample sliding frames every 160 samples
7	 *             -> feature ring (KWS_RING frames of 40)
8	 *             -> every KWS_INFER_EVERY frames, run the DS-CNN on the last
9	 *                KWS_T frames, average the last KWS_SMOOTH outputs, fire
10	 *                the callback when the average crosses the threshold,
11	 *                then hold off for KWS_REFRACT_FRAMES.
12	 *
13	 * Single consumer thread; the threshold may be poked from another thread
14	 * (word-sized float store, worst case one late decision).
15	 *
16	 * SPDX-License-Identifier: Apache-2.0
17	 ****************************************************************************/
18	
19	#include <string.h>
