27	/****************************************************************************
28	 * Private Data
29	 ****************************************************************************/
30	
31	static int16_t g_sbuf[KWS_WIN];
32	static int     g_sfill;
33	
34	static float   g_fring[KWS_RING][KWS_NMEL];
35	static int     g_fw;                     /* next write slot */
36	static uint32_t g_frames;
37	
38	static float   g_input[KWS_T * KWS_NMEL];
39	static float   g_smooth[KWS_SMOOTH];
40	static int     g_smooth_n;
41	
42	static volatile float g_threshold = KWS_DEFAULT_THRESHOLD;
43	static int     g_holdoff;
44	
45	static kws_detect_cb_t g_cb;
46	static void           *g_cb_arg;
47	
48	static kws_stats_t g_stats;
49	
50	static int16_t g_pcm_peak;      /* max |sample| seen since last peek */
51	
52	/****************************************************************************
53	 * Private Functions
54	 ****************************************************************************/
55	
56	static uint32_t now_us(void)
57	{
58	  struct timespec ts;
59	
60	  clock_gettime(CLOCK_MONOTONIC, &ts);
61	  return (uint32_t)(ts.tv_sec * 1000000ll + ts.tv_nsec / 1000);
62	}
63	
64	static void run_inference(void)
65	{
66	  uint32_t t0 = now_us();
67	  int start = g_fw - KWS_T;
68	  float prob;
69	  float sum;
70	  int i;
71	  int n;
72	
73	  if (start < 0)
74	    {
75	      start += KWS_RING;
76	    }
77	
78	  for (i = 0; i < KWS_T; i++)
79	    {
80	      int idx = start + i;
81	
82	      if (idx >= KWS_RING)
83	        {
84	          idx -= KWS_RING;
85	        }
