91	  prob = kws_nn_infer(g_input);
92	
93	  g_smooth[g_stats.inferences % KWS_SMOOTH] = prob;
94	  if (g_smooth_n < KWS_SMOOTH)
95	    {
96	      g_smooth_n++;
97	    }
