102	    {
103	      sum += g_smooth[i];
104	    }
105	
106	  sum /= (float)n;
107	
108	  g_stats.inferences++;
109	  g_stats.last_prob = prob;
110	  g_stats.smoothed = sum;
111	  g_stats.infer_us = now_us() - t0;
112	  if (sum > g_stats.peak)
113	    {
114	      g_stats.peak = sum;
115	    }
116	
117	  if (g_holdoff == 0 && sum >= g_threshold)
118	    {
119	      g_stats.detections++;
120	      g_holdoff = KWS_REFRACT_FRAMES;
121	      if (g_cb != NULL)
122	        {
123	          g_cb(sum, g_cb_arg);
124	        }
125	    }
126	}
