150	void kws_engine_init(kws_detect_cb_t cb, void *arg)
151	{
152	  memset(&g_stats, 0, sizeof(g_stats));
153	  memset(g_smooth, 0, sizeof(g_smooth));
154	  g_sfill = 0;
155	  g_fw = 0;
156	  g_frames = 0;
157	  g_smooth_n = 0;
158	  g_holdoff = KWS_WARMUP_FRAMES;
159	  g_cb = cb;
160	  g_cb_arg = arg;
161	}
162	
163	void kws_engine_push(const int16_t *pcm, size_t n)
164	{
165	  size_t i;
166	
167	  for (i = 0; i < n; i++)
168	    {
169	      int16_t v = pcm[i] < 0 ? -pcm[i] : pcm[i];
170	
171	      if (v > g_pcm_peak)
172	        {
173	          g_pcm_peak = v;
174	        }
175	    }
176	
177	  while (n > 0)
178	    {
179	      size_t take = (size_t)(KWS_WIN - g_sfill);
180	
181	      if (take > n)
182	        {
183	          take = n;
184	        }
185	
186	      memcpy(&g_sbuf[g_sfill], pcm, take * sizeof(int16_t));
187	      g_sfill += (int)take;
188	      pcm += take;
189	      n -= take;
190	
191	      if (g_sfill == KWS_WIN)
192	        {
193	          push_frame();
194	          memmove(g_sbuf, &g_sbuf[KWS_HOP],
195	                  (KWS_WIN - KWS_HOP) * sizeof(int16_t));
196	          g_sfill = KWS_WIN - KWS_HOP;
197	        }
198	    }
199	}
