238	/****************************************************************************
239	 * Name: kws_engine_selftest / kws_engine_peek
240	 *
241	 * Description:
242	 *   Diagnostics.  selftest pushes all-zero and all-one feature windows
243	 *   straight through the network — the two probabilities are functions of
244	 *   the weights alone, so a mismatch against the host harness pinpoints
245	 *   broken numerics on the target (libm, fast-math, ...).  peek exposes
246	 *   what the engine actually receives: the raw-PCM peak since the last
247	 *   call and three coefficients of the newest feature frame.
248	 *
249	 ****************************************************************************/
250	
251	void kws_engine_selftest(float *p_zero, float *p_one)
252	{
253	  int i;
254	
255	  for (i = 0; i < KWS_T * KWS_NMEL; i++)
256	    {
257	      g_input[i] = 0.0f;
258	    }
259	
260	  *p_zero = kws_nn_infer(g_input);
261	
262	  for (i = 0; i < KWS_T * KWS_NMEL; i++)
263	    {
264	      g_input[i] = 1.0f;
265	    }
266	
267	  *p_one = kws_nn_infer(g_input);
268	}
269	
270	void kws_engine_peek(int16_t *pcm_peak, float feat[3])
271	{
272	  int last = g_fw - 1;
273	
274	  if (last < 0)
275	    {
276	      last += KWS_RING;
277	    }
278	
279	  *pcm_peak = g_pcm_peak;
280	  g_pcm_peak = 0;
281	  feat[0] = g_fring[last][0];
282	  feat[1] = g_fring[last][10];
283	  feat[2] = g_fring[last][39];
284	}
